  h.restore('r', 1, 'ana');
  assert.deepEqual(h.get('r'), { a: 1, b: 1 }, 'restore removes fields added later');
  assert.deepEqual(h.at('r', 5), { a: 5, b: 2 }, 'and every version before it is still there');

